    idl_q->ordinal = AUDIO_STREAM_SET_TITLE;
    if (idl_st == OK && (!idl_put(idl_b0, &idl_qn, title, title_len, 63, 1) ||
                             !idl_str_ok(title, title_len)))
        idl_st = ERR_INVALID_ARGS;
